'use strict';
const q=new URLSearchParams(location.search),variant=document.body.dataset.variant;
const theme=q.get('theme')==='night'?'night':'paper';
document.documentElement.classList.toggle('night',theme==='night');
const scenario=window.STATES.find(s=>s.id===q.get('state'))||window.STATES[0];
const journal=document.querySelector('#journal'),dialog=document.querySelector('#training'),body=document.querySelector('#sheet-body');
const fmt=n=>Number(n).toLocaleString('en-US',{maximumSignificantDigits:21});
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const m={base:scenario.unavailable?null:2126,addition:scenario.addition??null,draft:scenario.draft||'',editing:scenario.editing??scenario.addition==null,consent:!!scenario.consent,pending:!!scenario.pending,error:scenario.error||'',failed:!!scenario.failed,health:scenario.health||'fresh',operation:0,lastAction:scenario.id};
const target=()=>m.base==null?null:m.base+(m.addition??0);
const rowLabel=()=>target()==null?'Usual target · unavailable':`${m.addition==null?'Usual day':'Training day'} · ${fmt(target())} kcal`;
function numeric(){const s=m.draft.trim();return s!==''&&/^\+?(?:\d+(?:\.\d*)?|\.\d+)$/.test(s)&&Number.isFinite(Number(s))&&Number(s)>0&&Number.isFinite(m.base+Number(s))?Number(s):null;}
const canConfirm=()=>m.base!=null&&numeric()!=null&&!m.pending&&(!scenario.manual||m.consent);
function renderToday(){
 const meals=scenario.meals||'normal',foods=window.FIXTURE.foods;
 const total=foods.reduce((n,f)=>n+f.kcal,0),macros=['p','c','f'].map(k=>foods.reduce((s,f)=>s+f[k],0));
 const absent=['loading','error'].includes(meals),partial=meals==='partial',eaten=meals==='empty'?0:total;
 journal.innerHTML=`<aside class="folio" aria-hidden="true">16 SEP / FOOD JOURNAL</aside><p class="study">${variant.toUpperCase()} · ${variant==='a'?'Open journal':'Ruled form'} / ${theme==='night'?'Night':'Paper'}<br>Design prototype · fictional records · no server writes</p><header><div><time>16 SEP · WEDNESDAY</time><h1>Today</h1></div><div class="chrome" aria-label="Unchanged Add and Settings context; not part of prototype"><span aria-hidden="true">＋</span><span aria-hidden="true">⚙</span></div></header><section class="readout" aria-label="Food calories"><svg class="ring" viewBox="0 0 90 90" aria-hidden="true"><circle cx="45" cy="45" r="34" fill="none" stroke="var(--inkline)"/><circle cx="45" cy="45" r="28" fill="none" stroke="var(--field)" stroke-width="10"/>${!absent&&!partial&&target()!=null?`<circle cx="45" cy="45" r="28" fill="none" stroke="var(--accent)" stroke-width="10" pathLength="100" stroke-dasharray="${Math.min(100,eaten/target()*100)} 100" transform="rotate(-90 45 45)"/>`:''}<circle cx="45" cy="45" r="21" fill="none" stroke="var(--inkline)" stroke-width=".7"/><path d="M45 7v14" stroke="var(--inkline)"/></svg><div><p class="eyebrow">Eaten</p><p class="totals">${absent?'—':partial?'—':fmt(eaten)} <span>kcal</span></p><p class="remaining">${absent?'Records unavailable':partial?'Nutrition incomplete':'From your logged food'}</p></div></section><button class="training-row ${m.addition!=null?'confirmed':''}" id="training-row" aria-haspopup="dialog"><span class="num">${rowLabel()}</span><span class="arrow" aria-hidden="true">›</span></button>${!absent&&!partial?`<section class="macros" aria-label="Protein, carbs and fat">${['Protein','Carbs','Fat'].map((label,i)=>`<div class="macro" style="--pigment:var(--${label.toLowerCase()})"><span>${label}</span><span class="rail" aria-hidden="true"><i style="width:${meals==='empty'?0:Math.min(100,macros[i]/window.FIXTURE.macroGoals[i]*100)}%"></i></span><span class="mono">${meals==='empty'?0:macros[i]} / ${window.FIXTURE.macroGoals[i]} g</span></div>`).join('')}</section>`:''}${meals==='empty'?'<p class="page-note">No meals logged yet.</p>':meals==='loading'?'<p class="page-note" role="status">Loading your diary…<br>No readable target yet.</p>':meals==='error'?'<p class="page-note" role="alert">Couldn’t load the diary.<br>No records or target are available.</p>':`${meals==='stale'?'<p class="page-note">Showing saved diary records.<br>Last checked 16 Sep, 12:30. Refresh unavailable.</p>':''}${meals==='multi'?foodGroup('Breakfast',foods.slice(0,1),'08:10',false):''}${foodGroup('Lunch',meals==='multi'?foods.slice(1):foods,'12:30',partial)}`}<p class="page-note">${meals==='partial'?'One item has no calorie value. The daily total is unavailable.':'Illustrations identify foods; they are not meal photos.'}</p><nav class="nav" aria-label="Unchanged navigation shown for context only"><span>Today</span><span>History</span><span>Goals</span></nav>`;
 document.querySelector('#training-row').onclick=()=>openSheet();
}
function foodGroup(name,foods,time,partial){return `<div class="meal-title"><h2>${name}</h2><span class="mono">${time} · ${partial?'Incomplete':fmt(foods.reduce((s,f)=>s+f.kcal,0))+' kcal'}</span></div><section aria-label="${name} foods">${foods.map((f,i)=>`<div class="food ${f.confidence<.7?'review':''}"><img src="assets/a-${theme}-${f.id}.svg" alt=""><div><p class="name">${esc(f.name)}</p><p class="portion mono">${f.quantity} ${f.unit} · P ${f.p}g · C ${f.c}g · F ${f.f}g</p><p class="provenance">${esc(f.source)}${f.confidence<.7?' · <span class="verify-label">verify</span>':''}</p></div><div class="kcal">${partial&&i===0?'—':f.kcal}<small>kcal</small></div></div>`).join('')}</section>`;}
function reading(label){
 const h=m.health,missing=['missing','denied','error','loading'].includes(h)||(h==='partial'&&label==='Workout')||(h==='workout-only'&&label==='Movement');
 const stale=h==='stale';
 const value=missing?'Unavailable':label==='Movement'?(h==='zero'?'0 kcal':'386 kcal'):(h==='zero'?'Strength training · 0 min':'Strength training · 48 min');
 const source=label==='Movement'?'Apple Health · active energy':'Apple Health · Apple Watch';
 const sample=stale?(label==='Movement'?'14 Sep 2026, 18:10':'13 Sep 2026, 07:40'):'16 Sep 2026, 12:20';
 return `<div class="reading" data-reading="${label}"><div class="reading-head"><span>${label}</span><span class="num">${value}</span></div><p>${missing?(h==='loading'?'Apple Health · reading…':h==='error'?'Apple Health · read failed':'Apple Health · no readable data'):`${stale?'<span class="stale-label">Last known · not today’s total</span>':''}Sample: <span class="num">${sample}</span><br>${source}`}<br>${h==='loading'?'Check in progress':`Checked: <span class="num">16 Sep 2026, 12:35</span>`}</p></div>`;
}
function renderSheet(){
 const editing=m.editing||m.addition==null,unavailable=m.base==null;
 body.innerHTML=`<section class="sheet-section" data-section="answer"><h3>Today's answer</h3><p class="context-line">${unavailable?'Usual target · unavailable':`Usual target · <span class="num">${fmt(m.base)} kcal</span>`}<small>${unavailable?'No readable target for this date.':`Source: ${scenario.manual?'manual goal':'computed from your profile'}.`}</small></p>${editing?`<p class="intro">For a longer or harder session, enter an addition from your own plan.</p><form id="answer-form" novalidate><div class="amount-grid"><label class="field-label" for="amount">Add for this day</label><div class="field-row"><input id="amount" name="amount" type="text" inputmode="decimal" autocomplete="off" placeholder="Your amount" value="${esc(m.draft)}" ${unavailable||m.pending?'disabled':''} aria-describedby="amount-hint answer-status"><span>kcal</span></div></div><p class="hint" id="amount-hint">No amount suggested. This screen cannot assess adequate fuelling.</p>${scenario.manual?`<label class="consent"><input id="consent" type="checkbox" ${m.consent?'checked':''} ${m.pending||unavailable?'disabled':''}><span>I choose a day-only change; keep my saved manual goal.</span></label>`:''}<p id="answer-status" class="status ${m.error?'error':''}" role="${m.error?'alert':'status'}">${m.pending?'Applying local note… Target unchanged until confirmation completes.':esc(m.error)||(unavailable?'You can review context; confirmation needs a readable target.':'')}</p><div class="actions"><button id="confirm" class="primary" type="submit" ${canConfirm()?'':'disabled'}>${m.failed?'Retry confirmation':'Confirm for this day'}</button><button id="cancel" class="link-button" type="button">Cancel</button></div></form>`:`<p class="intro">You confirmed an addition for a longer or harder session.</p><p class="confirmed-note num">+${fmt(m.addition)} kcal · this day only</p><p class="hint">No amount suggested. This screen cannot assess adequate fuelling.</p><div class="actions"><button id="edit" class="secondary">Edit amount</button><button id="undo" class="link-button">Undo adjustment</button></div><p id="answer-status" class="status" role="status">${m.lastAction==='confirmed'?'Confirmed. Today’s row is updated.':''}</p>`}<p class="local">This session only · not synced.<br>Saved goals and macros stay unchanged.</p></section><section class="sheet-section" data-section="readings"><h3>Readings</h3>${reading('Movement')}${reading('Workout')}${m.health==='error'?'<p class="status error" role="alert">Couldn’t read Apple Health. Nothing changed. Try again below.</p>':''}</section><section class="sheet-section caveats" data-section="about"><h3>About this context</h3><p>Food-target comparison, not a fuelling assessment.</p><p>Movement includes activity beyond workouts. It is context, not a calorie bonus.</p><p>Health may be missing or not shared; that does not mean a rest day.</p><p>Dates belong to the samples, and checked times describe these reads. Overlap with your usual target is unknown.</p><p>For a personal fuelling plan, consult a sports dietitian.</p><button id="read-health" class="health-read" ${m.health==='loading'?'disabled':''}>${m.health==='loading'?'Reading Apple Health…':'Read Apple Health'}</button><p id="health-status" class="status" role="status"></p><p class="local">Local to this signed-in session, not saved to Health or synced. No meal, future goal or historical target changes.</p><p class="local">Prototype only. Health states are simulated; no Health access or writes.</p></section>`;
 const amount=document.querySelector('#amount');
 if(amount)amount.oninput=()=>{m.draft=amount.value;m.error=m.draft.includes(',')?'Use a decimal point, without grouping commas.':m.draft.trim()!==''&&numeric()==null?'Enter a finite amount greater than zero. To remove a confirmed addition, use Undo.':'';updateValidation();};
 const consent=document.querySelector('#consent');if(consent)consent.onchange=()=>{m.consent=consent.checked;updateValidation();};
 const form=document.querySelector('#answer-form');if(form)form.onsubmit=e=>{e.preventDefault();confirm();};
 const cancel=document.querySelector('#cancel');if(cancel)cancel.onclick=()=>closeSheet();
 const edit=document.querySelector('#edit');if(edit)edit.onclick=()=>{m.editing=true;m.draft=String(m.addition);m.consent=false;m.error='';m.lastAction='edit';renderSheet();dialog.scrollTop=0;};
 const undo=document.querySelector('#undo');if(undo)undo.onclick=()=>{m.operation++;m.addition=null;m.draft='';m.consent=false;m.editing=true;m.error='';m.lastAction='undo';renderToday();renderSheet();document.querySelector('#answer-status').textContent='Addition removed. Your saved goal and meals are unchanged.';dialog.scrollTop=0;};
 document.querySelector('#read-health').onclick=()=>{const previous=m.health;m.health='loading';renderSheet();document.querySelector('#health-status').textContent='Simulated read in progress…';setTimeout(()=>{m.health=previous==='error'?'missing':previous;renderSheet();document.querySelector('#health-status').textContent='Simulated read finished. No real Health data was read.';document.querySelector('#read-health').focus({preventScroll:true});},500);};
}
function updateValidation(){const status=document.querySelector('#answer-status');status.textContent=m.error;status.classList.toggle('error',!!m.error);status.setAttribute('role',m.error?'alert':'status');document.querySelector('#confirm').disabled=!canConfirm();document.querySelector('#amount').setAttribute('aria-invalid',String(!!m.error));}
function openSheet(){m.draft=m.addition==null?'':String(m.addition);m.editing=m.addition==null;m.consent=false;m.error='';m.failed=false;m.pending=false;renderSheet();dialog.showModal();dialog.scrollTop=0;document.querySelector('#close').focus({preventScroll:true});}
function closeSheet(){m.operation++;m.pending=false;dialog.close();document.querySelector('#training-row').focus({preventScroll:true});}
function confirm(){if(!canConfirm())return;const amount=numeric(),operation=++m.operation;m.pending=true;m.error='';m.lastAction='pending';renderSheet();setTimeout(()=>{if(operation!==m.operation||!dialog.open)return;m.pending=false;if(q.get('save')==='failure'&&!m.failed){m.failed=true;m.error='Could not apply this local note. Nothing changed. Retry or cancel.';m.lastAction='error';renderSheet();return;}m.addition=amount;m.editing=false;m.failed=false;m.lastAction='confirmed';renderToday();renderSheet();dialog.scrollTop=0;document.querySelector('#edit').focus({preventScroll:true});},500);}
function rollover(){m.operation++;m.pending=false;m.base=null;m.addition=null;m.draft='';m.consent=false;m.editing=true;m.error='The day changed. Nothing applied; cancel and review the new day.';m.lastAction='rollover';renderToday();if(dialog.open)renderSheet();}
document.querySelector('#close').onclick=closeSheet;
dialog.addEventListener('cancel',e=>{e.preventDefault();closeSheet();});
window.demoInspect=()=>({variant,theme,scenario:scenario.id,...m,target:target(),row:rowLabel(),open:dialog.open,canConfirm:canConfirm()});
window.demoRollover=rollover;
renderToday();
if(scenario.sheet){renderSheet();dialog.showModal();dialog.scrollTop=0;document.querySelector('#close').focus({preventScroll:true});}
